NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Jude'

CHAPTERS = {
    1: {
        1: 'Juuda, Jeesuksen Kristuksen palvelija ja Jaakobin veli, kutsutuille, jotka ovat Isässä Jumalassa pyhitettyjä ja Jeesukselle Kristukselle varjeltuja.',
        2: 'Lisääntyköön teille laupeus, rauha ja rakkaus.',
        3: 'Rakkaani! Kun minulla on ollut kaikkea halua kirjoittaa teille yhteisestä pelastuksestamme, minulle tuli pakko kirjoittaa ja kehottaa teitä kilvoittelemaan sen uskon puolesta, joka on annettu kerta kaikkiaan pyhille.',
        4: 'Sillä teidän keskuuteenne on pujahtanut eräitä ihmisiä, joiden jo aikoja sitten on kirjoitettu tulevan tähän tuomioon, jumalattomia, jotka kääntävät Jumalamme armon riettaudeksi ja kieltävät ainoan Valtiaamme ja Herramme, Jeesuksen Kristuksen.',
        5: 'Vaikka jo kerran olette saaneet tietää tämän, tahdon kuitenkin muistuttaa teitä siitä, että Herra, joka oli pelastanut kansan Egyptistä, toisella kertaa hukutti ne, jotka eivät uskoneet;',
        6: 'Hän myös pani ne enkelit, jotka eivät säilyttäneet alkutilaansa, vaan jättivät oman asumuksensa, pimeyteen iankaikkisissa kahleissa säilytettäviksi suuren päivän tuomioon.',
        7: 'Samoin ovat Sodoma ja Gomorra ja niiden ympärillä olevat kaupungit, jotka harjoittivat haureutta samalla tavalla kuin nekin ja eksyivät vieraan lihan perään, varoittavana esimerkkinä kärsiessään iankaikkisen tulen rangaistusta.',
        8: 'Yhtäkaikki nämä uneksijat samoin saastuttavat lihan. He halveksivat herruutta ja herjaavat voimakkaita henkiä.',
        9: 'Mutta ylienkeli Miikaelkaan, kun riiteli ja väitteli perkeleen kanssa Mooseksen ruumiista, ei rohjennut lausua herjaavaa tuomiota, vaan sanoi: "Rangaiskoon sinua Herra!"',
        10: 'Nämä herjaavat sitä vastoin kaikkea sitä, mitä eivät tunne, mutta minkä he järjettömien eläinten tavoin luonnostaan ymmärtävät ja turmelevat sillä itsensä.',
        11: 'Voi heitä, sillä he ovat lähteneet Kainin tielle ja heittäytyneet palkan tähden Bileamin eksytykseen ja hukkuvat kapinoidessaan kuin Koora!',
        12: 'He ovat likapilkkuja rakkauden aterioillanne ja kestitsevät itseään arkailematta. He ovat vedettömiä, tuulten ajamia pilviä, paljaita, syksyisiä puita, hedelmättömiä, kahdesti kuolleita, juurineen reväistyjä,',
        13: 'rajuja meren aaltoja, jotka vaahtoavat omia häpeitään, harhailevia tähtiä, joille pimeyden synkeys on ikuisesti varattu.',
        14: 'Heistäkin Heenok, Aadamista seitsemäs, on ennustanut sanoen: "Katso, Herra tulee kymmenien tuhansien pyhiensä kanssa',
        15: 'tuomitsemaan kaikkia ja rankaisemaan kaikkia jumalattomia kaikista heidän jumalattomista teoistaan, joita he ovat tehneet jumalattomuudessaan, ja kaikista kovista sanoista, mitä nuo jumalattomat syntiset ovat puhuneet häntä vastaan."',
        16: 'He ovat napisijoita, kohtaloonsa tyytymättömiä ja vaeltavat himojensa mukaan. Heidän suunsa puhuu kopeita sanoja, ja he mielistelevät ihmisiä oman etunsa tähden.',
        17: 'Mutta te, rakkaani, muistakaa näitä sanoja, jotka meidän Herramme Jeesuksen Kristuksen apostolit ovat edeltä puhuneet,',
        18: 'sanoen teille: "Viimeisenä aikana on oleva pilkkaajia, jotka vaeltavat jumalattomien himojensa mukaan."',
        19: 'Nämä itse aiheuttavat hajaannusta. He ovat sielullisia, Henkeä heillä ei ole.',
        20: 'Mutta te, rakkaani, rakentukaa pyhimmän uskonne varaan, rukoilkaa Pyhässä Hengessä',
        21: 'ja pysykää Jumalan rakkaudessa odottaessanne meidän Herramme Jeesuksen Kristuksen laupeutta iankaikkiseksi elämäksi.',
        22: 'Ja armahtakaa toisia, niitä, jotka epäilevät. Pelastakaa heidät, tulesta temmaten.',
        23: 'Toisia taas armahtakaa pelolla inhoten lihan tahraamaa vaatettakin.',
        24: 'Mutta hänelle, joka voi varjella teidät lankeamasta ja asettaa teidät nuhteettomina, riemuitsevina, kirkkautensa eteen,',
        25: 'hänelle, ainoalle viisaalle Jumalalle ja Vapahtajallemme, hänelle kunnia, valtasuuruus, voima ja valta sekä nyt että kaikkiin iankaikkisuuksiin! Aamen.',
    },
}
